@startuml

class Game {
  + hiddenTile : Tile
}

class Board {
  + spareConnectionPieces : int
}

class Tile {
  + isBlack : boolean
  + isActionTile : boolean
  + actionTileDuration : int
}

class Connection {
  + side : string
}

class ActionCard {
  + type : ActionType
}

enum ActionType {
  EXTRA_TURN
  CONNECT_ADJACENT_TILES
  REMOVE_CONNECTION
  MOVE_TO_ARBITRARY_TILE
  LOSE_NEXT_TURN
}

class Player {
  + color : string
  + startingPosition : Tile
}

class PlayingPiece {
  + color : string
}

class Die {
}

Game "1" *-- "1" Board
Board "1" *-- "*" Tile
Board "1" *-- "1" Deck
Board "1" *-- "*" Connection
Tile "1" -- "0..1" Connection : right
Tile "1" -- "0..1" Connection : left
Tile "1" -- "0..1" Connection : top
Tile "1" -- "0..1" Connection : bottom
Game "1" -- "2..4" Player
Player "1" -- "1" PlayingPiece
Game "1" -- "1" Die
Deck "1" *-- "32" ActionCard

@enduml

